import{_ as r,l as i,o as l,c as s,v as p,p as d,x as o,d as t,i as h,S as m,b as a}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"标签平滑","description":"","frontmatter":{"title":"标签平滑","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/label-smoothing-lm.md","filePath":"llm/label-smoothing-lm.md","lastUpdated":1789023840000}'),c={name:"llm/label-smoothing-lm.md"};function u(E,e,g,_,P,f){const n=i("Mermaid");return l(),s("div",null,[e[1]||(e[1]=p('<h1 id="标签平滑" tabindex="-1">标签平滑 <a class="header-anchor" href="#标签平滑" aria-label="Permalink to &quot;标签平滑&quot;">​</a></h1><div class="epigraph"><p>把 one-hot 目标改成正确类 $1-\\varepsilon$、其余均分 $\\varepsilon$，交叉熵不再奖励无限大的 logit 间隔，校准往往变好，最大似然则变差。</p><footer>—— Szegedy et al., Rethinking the Inception Architecture, CVPR 2016；分析见 Müller, Kornblith &amp; Hinton, NeurIPS 2019</footer></div><p><a href="/llm/attention-dropout-droppath">上一课</a>把激活与路由上的噪声写完。缺口转到<strong>目标</strong>侧：Vaswani 等人在翻译上用了 \\(\\varepsilon=0.1\\) 的标签平滑（label smoothing）。语言模型若仍把目标当 one-hot，CE 会推动正确类 logit 相对其余趋向 \\(+\\infty\\)，这与 <a href="/llm/output-init-logit-scale">输出初始化</a> 钉住的有限尺度、以及主干 <a href="/llm/z-loss">z-loss</a> 要压的 LSE，方向相反。本课写平滑如何改损失，以及因果 LM 为什么常常不用它。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准下一 token 损失是 \\(-\\log p_{y}\\)。最优是 \\(p_y=1\\)，需要 \\(\\ell_y-\\ell_j\\to\\infty\\)。训练中这意味着输出层与最后一层范数可以无界增长，半精度与校准先坏。Szegedy 等人把目标改成</p> \\[q_y=1-\\varepsilon,\\qquad q_j=\\frac{\\varepsilon}{|V|-1}\\ (j\\neq y), \\]<p>最小化 \\(\\mathrm{KL}(q\\|p)\\)（等价于对 \\(q\\) 的交叉熵）。正确类不再要求概率 1，错误类也分到一点质量，logit 间隔有限。Müller 等人指出：平滑抑制的是正确类相对最强错误类的过度自信，表示空间里同类更紧、类间更分离，对蒸馏当教师更友好。</p><p>因果 LM 的词表是 \\(10^4\\)–\\(10^5\\) 量级，\\(\\varepsilon/(|V|-1)\\) 极小。同样 \\(\\varepsilon=0.1\\)，分到每个错误 token 的目标质量可以忽略，平滑几乎只在「正确类不要 1」上起作用。翻译词表较小、且评测是 BLEU 不是 PPL，原论文的 0.1 不能直接贴到 GPT。</p><p><span class="marginnote">平滑改的是训练目标，不是解码温度。用平滑训完再以温度 1 解码，模型会偏「平」；若把温度降下来追 PPL，等于部分撤销平滑。报 PPL 的预训练不要默默开平滑。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现上不必物化 \\(q\\)：</p> \\[\\mathcal{L}=-(1-\\varepsilon)\\log p_y-\\varepsilon\\,\\mathrm{mean}_{j\\neq y}\\log p_j, \\]<p>第二项等于 \\(\\varepsilon\\) 乘（全体 token 的平均 \\(\\log p\\) 再扣掉正确类一项的修正）。与全词表 softmax 的融合核要一起改，Cut CE 一类只取正确类与分母的实现，必须补上对 \\(\\log p_j\\) 的均值，否则平滑是错的。</p><p>\\(\\varepsilon\\) 的扫：翻译 / 分类 0.1 是文献常客；LM 若用，数量级更小（0.01 或更低），并<strong>同时看</strong> CE 与下游，不要只看训练 CE——训练 CE 几乎必升。与 dropout 同时开时，噪声来源变两个，消融应能单独关平滑。</p><p>不要把平滑当成 class-balanced 的稀有词保护：它对所有错误类一视同仁，稀有词与高频词分到同样的 \\(\\varepsilon/(|V|-1)\\)。要照顾频次，应改采样或损失权重，不是加大 \\(\\varepsilon\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对 logits 的梯度从 \\(p-y\\) 变成 \\(p-q\\)。正确类目标变小，梯度不再拼命抬 \\(\\ell_y\\)；错误类目标非零，梯度轻微抬所有错误 logit——更准确地说，相对 softmax 均值做微小拉动。结果是 LSE 增长变慢，与 z-loss 同向但弱得多，不能替代 z-loss：平滑不显式惩罚 \\(z^2\\)，只改目标。</p><p>Müller 等人还观察到：平滑使教师的 \\(p\\) 更适合当蒸馏目标，因为不再接近 one-hot。若你的流水线没有蒸馏，这个优点不存在。对指令微调，平滑可能伤害「必须选确定答案」的题；对开放生成，可能减轻个别 token 的过度自信。要按任务消融，不要作为稳定训练的默认保险。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>标签平滑与 label noise（随机关错标签）不是同一件事：前者是确定的软目标，后者是随机错误。也不要和 Mixup / token dropout 混写。评测 PPL、BPB 必须在<strong>未平滑</strong>的 CE 上算，否则与历史检查点不可比。下一课的困惑度定义以硬目标 CE 为准；若训练用了平滑，日志里应同时打 <code>ce_hard</code> 与 <code>ce_smooth</code>。</p>',20)),(l(),d(m,null,{default:o(()=>[h(n,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E6%AD%A3%E7%A1%AE%E7%B1%BB%20y%22%5D%20--%3E%20Q%5B%22%E8%BD%AF%E7%9B%AE%E6%A0%87%20q%22%5D%0A%20%20EPS%5B%22epsilon%22%5D%20--%3E%20Q%0A%20%20Q%20--%3E%20KL%5B%22CE(q%2C%20p)%22%5D%0A%20%20P%5B%22%E6%A8%A1%E5%9E%8B%20p%22%5D%20--%3E%20KL%0A%20%20KL%20--%3E%20GAP%5B%22%E6%9C%89%E9%99%90%20logit%20%E9%97%B4%E9%9A%94%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[t("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"标签平滑把 one-hot 改成 \\(1-\\varepsilon\\) 与均分 \\(\\varepsilon\\)，阻止 CE 要求无限间隔。"),a("li",null,"大词表 LM 上每错误类分到的质量极小；翻译上的 0.1 不是 LM 默认。"),a("li",null,"训练 CE 会升；报 PPL 必须另打硬目标 CE。"),a("li",null,"它弱于 z-loss，也不是稀有词加权；与 dropout 分开消融。"),a("li",null,"出处：Szegedy et al., CVPR 2016；Müller, Kornblith & Hinton, NeurIPS 2019；Vaswani et al. 在翻译中的使用。")],-1))])}const v=r(c,[["render",u]]);export{q as __pageData,v as default};
